  'Pierwsze kroki': 'Перші кроки',
  '{done} z {total} gotowe': '{done} з {total} готово',
  '{done} z {total} kroków ukończonych': 'Виконано {done} з {total} кроків',
  'Zwiń': 'Згорнути',
  'Ukryj checklistę': 'Сховати чек-лист',
  'Wszystko gotowe — świetna robota!': 'Усе готово — чудова робота!',
  'Nie pokazuj tej listy': 'Не показувати цей список',
  'Menu główne': 'Головне меню',
  'Stąd przechodzisz do wszystkich modułów kościoła — członków, kalendarza, finansów i więcej. Widoczne są tylko te, do których masz dostęp.': 'Звідси ви переходите до всіх модулів церкви — учасників, календаря, фінансів тощо. Показуються лише ті, до яких у вас є доступ.',
  'Twój ekran startowy — skróty, nadchodzące wydarzenia i najważniejsze informacje w jednym miejscu.': 'Ваш стартовий екран — ярлики, найближчі події та найважливіша інформація в одному місці.',
  'Planuj nabożeństwa, spotkania i wydarzenia. Członkowie mogą zapisywać się (RSVP) i widzieć je w aplikacji.': 'Плануйте богослужіння, зустрічі та події. Учасники можуть реєструватися (RSVP) і бачити їх у застосунку.',
  'Baza osób w Twoim kościele — dane kontaktowe, grupy, obecność i notatki duszpasterskie.': 'База людей вашої церкви — контактні дані, групи, відвідуваність і пастирські нотатки.',
  'Szybkie wyszukiwanie': 'Швидкий пошук',
  'Naciśnij ⌘K (lub Ctrl+K), aby błyskawicznie znaleźć osobę, pieśń, grupę lub wydarzenie i przejść wprost do niej.': 'Натисніть ⌘K (або Ctrl+K), щоб миттєво знайти людину, пісню, групу чи подію та одразу перейти до неї.',
  'Język interfejsu': 'Мова інтерфейсу',
  'Przełączaj panel między polskim, angielskim i ukraińskim — każdy użytkownik wybiera własny.': 'Перемикайте панель між польською, англійською та українською — кожен користувач обирає свою.',
  'Lista pierwszych kroków': 'Список перших кроків',
  'Ten przycisk otwiera checklistę wdrożenia. Odhaczaj kroki, a poznasz system w kilka minut.': 'Ця кнопка відкриває чек-лист впровадження. Відмічайте кроки та опануйте систему за кілька хвилин.',
  'Pomoc zawsze pod ręką': 'Допомога завжди під рукою',
  'W każdej chwili kliknij tutaj, aby ponownie uruchomić samouczek albo otworzyć listę kroków.': 'Будь-коли натисніть тут, щоб знову запустити навчання або відкрити список кроків.',
  'Poznaj panel w minutę': 'Ознайомтеся з панеллю за хвилину',
  'Przejdź krótki interaktywny samouczek.': 'Пройдіть коротке інтерактивне навчання.',
  'Uzupełnij swój profil': 'Заповніть свій профіль',
  'Dodaj imię, zdjęcie i dane kontaktowe.': "Додайте ім'я, фото та контактні дані.",
  'Zobacz kalendarz wydarzeń': 'Перегляньте календар подій',
  'Sprawdź, jak planowane są nabożeństwa i spotkania.': 'Подивіться, як плануються богослужіння та зустрічі.',
  'Dodaj logo i kolory kościoła': 'Додайте логотип і кольори церкви',
  'Spersonalizuj wygląd panelu pod swoją społeczność.': 'Персоналізуйте вигляд панелі під свою спільноту.',
  'Włącz moduły, których używacie': 'Увімкніть модулі, якими користуєтесь',
  'Finanse, grupy domowe, uwielbienie, media i inne.': 'Фінанси, домашні групи, прославлення, медіа та інше.',
  'Dodaj pierwszych członków': 'Додайте перших учасників',
  'Zbuduj bazę osób swojego kościoła.': 'Побудуйте базу людей вашої церкви.',
  'Zaplanuj pierwszy program': 'Заплануйте першу програму',
  'Ułóż przebieg nabożeństwa i przypisz służby.': 'Складіть перебіг богослужіння та призначте служіння.',
  'Zaproś współpracowników': 'Запросіть команду',
