  'Kliknij tutaj, aby wrócić do samouczka lub otworzyć listę pierwszych kroków.': 'Натисніть тут, щоб повернутися до навчання або відкрити список перших кроків.',
  'Znajdź wszystko w sekundę': 'Знайдіть усе за секунду',
  'Naciśnij ⌘K / Ctrl+K, aby wyszukać osoby, pieśni, grupy i wydarzenia.': 'Натисніть ⌘K / Ctrl+K, щоб шукати людей, пісні, групи та події.',
