  'Witaj w Avenit! 👋': 'Ласкаво просимо до Avenit! 👋',
  'To Twój panel do zarządzania kościołem. Skonfigurujmy go w kilka minut, a potem pokażemy Ci najważniejsze funkcje.': 'Це ваша панель керування церквою. Налаштуймо її за кілька хвилин, а потім покажемо основні функції.',
  'To Twój panel kościoła. Pokażemy Ci w minutę, jak się w nim odnaleźć i korzystać z najważniejszych funkcji.': 'Це панель вашої церкви. За хвилину покажемо, як тут орієнтуватися та користуватися основними функціями.',
