  'Aby korzystać z członków w tym module, utwórz tabelę w Supabase.': 'Щоб використовувати учасників у цьому модулі, створіть таблицю в Supabase.',
  'Aby korzystać z wydarzeń w tym module, utwórz tabelę w Supabase.': 'Щоб використовувати події в цьому модулі, створіть таблицю в Supabase.',
  'Aby korzystać z zadań w tym module, utwórz tabelę w Supabase.': 'Щоб використовувати завдання в цьому модулі, створіть таблицю в Supabase.',
  'Brak aktywnej sesji. Przejdź do ustawień, aby utworzyć sesję.': 'Немає активної сесії. Перейдіть до налаштувань, щоб створити сесію.',
  'Brak członków. Dodaj członków w zakładce "Członkowie".': 'Немає учасників. Додайте учасників на вкладці «Учасники».',
  'Brak podpisu. Przejdź do zakładki HTML, aby dodać podpis.': 'Немає підпису. Перейдіть на вкладку HTML, щоб додати підпис.',
  'Brak programów nabożeństw. Dodaj programy w module "Programy".': 'Немає програм богослужінь. Додайте програми в модулі «Програми».',
  'Brak wysłanych kampanii. Wyślij pierwszą, aby zobaczyć statystyki.': 'Немає надісланих кампаній. Надішліть першу, щоб побачити статистику.',
  'Dodaj zakładki w Ustawienia → Zarządzanie → kliknij "Zakładki" przy module.': 'Додайте вкладки в Налаштування → Керування → натисніть «Вкладки» біля модуля.',
  'Dodawaj, edytuj i zmieniaj kolejność modułów aplikacji': 'Додавайте, редагуйте та змінюйте порядок модулів застосунку',
  'Gdy ktoś Cię przypisze do służby, zobaczysz to tutaj': 'Коли хтось призначить вас на служіння, ви побачите це тут',
  'Gotowy, aby zacząć?': 'Готові почати?',
  'Kliknij "Dodaj członka" aby dodać pierwszego członka': 'Натисніть «Додати учасника», щоб додати першого учасника',
  'Kliknij na blok, aby edytować jego właściwości. Dwukrotne kliknięcie na tekst umożliwia edycję inline.': 'Натисніть на блок, щоб редагувати його властивості. Подвійне клацання по тексту вмикає редагування на місці.',
  'Kody zapasowe pozwalają zalogować się, gdy nie masz dostępu do aplikacji Google Authenticator.': 'Резервні коди дозволяють увійти, коли у вас немає доступу до застосунку Google Authenticator.',
  'Maksymalna liczba odpowiedzi, po której formularz zostanie zamknięty': 'Максимальна кількість відповідей, після якої форму буде закрито',
  'Najpierw dodaj członków w zakładce "Członkowie"': 'Спочатку додайте учасників на вкладці «Учасники»',
  'Nazwa wewnętrzna, nie będzie widoczna dla odbiorców': 'Внутрішня назва, не буде видна отримувачам',
  'Określ, które pola są wypełniane przez osobę zgłaszającą, a które przez każdego uczestnika.': 'Вкажіть, які поля заповнює заявник, а які — кожен учасник.',
  'Orby to rozmyte, kolorowe kule w tle formularza nadające mu nowoczesny wygląd.': 'Орби — це розмиті, кольорові кулі на фоні форми, що надають їй сучасного вигляду.',
  'Szablony systemowe nie mogą być edytowane. Użyj "Duplikuj" aby stworzyć własną wersję.': 'Системні шаблони не можна редагувати. Використайте «Дублювати», щоб створити власну версію.',
  'Temat, który odbiorcy zobaczą w skrzynce': 'Тема, яку отримувачі побачать у скриньці',
  'Transakcja zarejestrowana! Kliknij poniżej, aby przejść do płatności.': 'Транзакцію зареєстровано! Натисніть нижче, щоб перейти до оплати.',
  'Twoje konto zostało utworzone. Ustaw hasło, aby się zalogować.': 'Ваш обліковий запис створено. Встановіть пароль, щоб увійти.',
  'Twórz, planuj i analizuj kampanie SMS przez bramkę SMSAPI.pl.': 'Створюйте, плануйте та аналізуйте SMS-кампанії через шлюз SMSAPI.pl.',
  'Twórz, planuj i analizuj powiadomienia push wysyłane do web i mobile.': 'Створюйте, плануйте та аналізуйте push-сповіщення для вебу та мобільних.',
  'Wprowadź kod z aplikacji Google Authenticator, aby wyłączyć uwierzytelnianie dwuskładnikowe.': 'Введіть код із застосунку Google Authenticator, щоб вимкнути двофакторну автентифікацію.',
  'Wszystkie widgety są ukryte. Kliknij "Dostosuj", aby je włączyć.': 'Усі віджети приховано. Натисніть «Налаштувати», щоб увімкнути їх.',
  'Wybierz plan, aby korzystać z pełnych możliwości aplikacji.': 'Виберіть план, щоб користуватися всіма можливостями застосунку.',
  'Wybierz pole z formularza, aby edytować jego ustawienia': 'Виберіть поле з форми, щоб редагувати його налаштування',
  'Wybierz pole z palety po lewej stronie i przeciągnij je tutaj, aby zbudować formularz': 'Виберіть поле з палітри ліворуч і перетягніть його сюди, щоб побудувати форму',
  'Wybierz widoczne widgety i dostosuj ich rozmiar. Możesz również przeciągać widgety na pulpicie, aby zmienić ich kolejność.': 'Виберіть видимі віджети та налаштуйте їхній розмір. Ви також можете перетягувати віджети на панелі, щоб змінити їхній порядок.',
  'Wypełnij pole email w formularzu, aby móc dokonać płatności.': 'Заповніть поле email у формі, щоб мати змогу здійснити платіж.',
  'Wyślij swój pierwszy mail, aby zobaczyć szczegółowe statystyki': 'Надішліть свій перший лист, щоб побачити детальну статистику',
  'Wyślij testową wersję emaila na wskazany adres, aby sprawdzić jak będzie wyglądać przed wysłaniem do odbiorców.': 'Надішліть тестову версію листа на вказану адресу, щоб перевірити, як вона виглядатиме перед надсиланням отримувачам.',
