  'Dla wybranego typu włącz/wyłącz wbudowane zakładki wydarzenia oraz dodaj własne (nazwy po przecinku). „Szczegóły" są zawsze widoczne.': 'Для вибраного типу увімкніть/вимкніть вбудовані вкладки події та додайте власні (назви через кому). «Деталі» завжди видимі.',
