  'Możesz połączyć zewnętrzne konta e-mail (Gmail, Outlook, inne), aby odbierać i wysyłać wiadomości bezpośrednio z tej aplikacji. Wymaga to podania danych IMAP/SMTP Twojego dostawcy poczty.': 'Ви можете підключити зовнішні поштові акаунти (Gmail, Outlook, інші), щоб отримувати й надсилати повідомлення безпосередньо з цього застосунку. Для цього потрібні дані IMAP/SMTP вашого поштового провайдера.',
