  'Stąd przechodzisz do modułów kościoła. Są pogrupowane (np. Ludzie, Służby, Komunikacja) — kliknij nagłówek grupy, aby ją zwinąć lub rozwinąć. Widzisz tylko moduły, do których masz dostęp.': 'Звідси ви переходите до модулів церкви. Вони згруповані (напр. Люди, Служіння, Комунікація) — натисніть заголовок групи, щоб її згорнути або розгорнути. Ви бачите лише модулі, до яких маєте доступ.',
