  'Zwykle nic tu nie trzeba wpisywać — aplikacja używa wtedy wspólnej konfiguracji Avenit. Własne dane podaj tylko wtedy, gdy Twój kościół ma osobną aplikację logowania u Google lub Microsoft.': 'Зазвичай тут нічого не потрібно вводити — тоді застосунок використовує спільну конфігурацію Avenit. Власні дані вказуйте лише тоді, коли ваша церква має окремий застосунок входу в Google або Microsoft.',
