  'Włączaj i ukrywaj moduły w menu, zmieniaj ich nazwy, ikony i kolejność.': 'Вмикайте й приховуйте модулі в меню, змінюйте їхні назви, значки та порядок.',
  'Przełącznik pokazuje lub ukrywa moduł w menu. Ołówek zmienia nazwę i ikonę — nowa nazwa pojawi się w menu i w nagłówku modułu. Przeciągnij wiersz, aby zmienić kolejność. Moduły wbudowane można ukryć, ale nie usunąć.': 'Перемикач показує або приховує модуль у меню. Олівець змінює назву та значок — нова назва з\'явиться в меню та в заголовку модуля. Перетягніть рядок, щоб змінити порядок. Вбудовані модулі можна приховати, але не видалити.',
  'Klucz może zawierać tylko małe litery, cyfry i znak podkreślenia (_)': 'Ключ може містити лише малі літери, цифри та знак підкреслення (_)',
