  'Zgłoszenie trafi do administratorów kościoła. Napisz krótko, co jest nie tak (opcjonalnie).': 'Скарга надійде адміністраторам церкви. Коротко опишіть, що не так (необов\'язково).',
  'np. obraźliwe treści, spam': 'напр. образливий вміст, спам',
  'Wyślij zgłoszenie': 'Надіслати скаргу',
  'Nie udało się wysłać zgłoszenia. Spróbuj ponownie.': 'Не вдалося надіслати скаргу. Спробуйте ще раз.',
  'Dziękujemy. Zgłoszenie trafiło do administratorów.': 'Дякуємо. Скаргу передано адміністраторам.',
  'Zablokować: {name}?': 'Заблокувати: {name}?',
  'Nie dostaniesz od tej osoby wiadomości prywatnych, a jej wiadomości w grupach będą schowane. Ta osoba nie zobaczy, że ją zablokowano. Możesz to cofnąć w każdej chwili.': 'Ви не отримуватимете приватних повідомлень від цієї особи, а її повідомлення в групах буде приховано. Вона не побачить, що її заблоковано. Це можна скасувати будь-коли.',
  'Zablokowano: {name}': 'Заблоковано: {name}',
  'Nie udało się zablokować osoby. Spróbuj ponownie.': 'Не вдалося заблокувати особу. Спробуйте ще раз.',
  'Odblokowano: {name}': 'Розблоковано: {name}',
  'Nie udało się odblokować osoby. Spróbuj ponownie.': 'Не вдалося розблокувати особу. Спробуйте ще раз.',
  'Wczytuję starsze wiadomości…': 'Завантаження старіших повідомлень…',
  'Ta osoba jest zablokowana. Nie dostaniesz od niej wiadomości.': 'Цю особу заблоковано. Ви не отримуватимете від неї повідомлень.',
  'Odblokuj': 'Розблокувати',
  'Rozmowa prywatna z tą osobą nie jest dozwolona w Twoim kościele. Możesz napisać do niej w grupie.': 'Приватна розмова з цією особою не дозволена у вашій церкві. Ви можете написати їй у групі.',
  'Rozmowy prywatne są w Twoim kościele wyłączone. Możesz pisać w grupach i kanałach.': 'Приватні розмови у вашій церкві вимкнено. Ви можете писати в групах і каналах.',
  'Rozmowę prywatną możesz zacząć tylko z liderem albo administratorem.': 'Почати приватну розмову можна лише з лідером або адміністратором.',
  'Rozmowy prywatne z dorosłymi spoza rodziny są wyłączone. Z liderami rozmawiaj w grupie.': 'Приватні розмови з дорослими поза родиною вимкнено. З лідерами спілкуйтеся в групі.',
  'W Twoim kościele rozmowy prywatne mają ograniczenia. Na liście są osoby, do których możesz napisać.': 'У вашій церкві приватні розмови обмежено. У списку — люди, яким ви можете написати.',
