  'Rozmowa wyciszona': 'Звук розмови вимкнено',
  'Kto może zaczynać rozmowy prywatne i jak chronimy osoby niepełnoletnie.': 'Хто може починати приватні розмови і як ми захищаємо неповнолітніх.',
  'Rozmowy prywatne (1:1)': 'Приватні розмови (1:1)',
  'Nikt nie zacznie nowej rozmowy prywatnej. Grupy i kanały działają jak dotąd.': 'Ніхто не зможе почати нову приватну розмову. Групи й канали працюють як раніше.',
  'Rozmowa prywatna jest możliwa, gdy jedną ze stron jest lider (służby lub grupy) albo administrator.': 'Приватна розмова можлива, коли одна зі сторін — лідер (служіння чи групи) або адміністратор.',
  'Każdy może napisać do każdego.': 'Кожен може написати кожному.',
  'Wszyscy ze wszystkimi': 'Усі з усіма',
  'Tylko z liderem lub administratorem': 'Лише з лідером або адміністратором',
  'Chroń osoby niepełnoletnie': 'Захищати неповнолітніх',
  'Blokuje rozmowy prywatne między osobą poniżej 18 lat a dorosłym (na podstawie daty urodzenia w kartotece). Rozmowy w grupach i kanałach są dozwolone.': 'Блокує приватні розмови між особою до 18 років і дорослим (на основі дати народження в картотеці). Розмови в групах і каналах дозволені.',
  'Prywatne zdjęcia i pliki z czatu': 'Приватні фото й файли з чату',
  'Pliki z rozmów otworzy tylko uczestnik rozmowy. Włącz, gdy wszyscy mają aktualną aplikację mobilną — starsze wersje nie pokażą wtedy zdjęć.': 'Файли з розмов зможуть відкрити лише учасники розмови. Увімкніть, коли всі матимуть актуальний мобільний застосунок — старіші версії тоді не показуватимуть фото.',
