  'Zbliżacie się do limitu planu. Gdy go przekroczycie, macie jeszcze 10% zapasu.': 'Ви наближаєтеся до ліміту плану. Якщо перевищите його, у вас ще є 10% запасу.',
  'Limit planu jest przekroczony, ale mieścicie się w 10% zapasie. Plan zmienimy od kolejnego okresu rozliczeniowego, nic nie jest blokowane.': 'Ліміт плану перевищено, але ви в межах 10% запасу. Ми змінимо план з наступного розрахункового періоду, нічого не блокується.',
  'Liczba dorosłych przekracza limit planu i 10% zapas. Wybierzcie większy plan poniżej, zmienimy go od kolejnego okresu. Nikt nie zostanie zablokowany.': 'Кількість дорослих перевищує ліміт плану і 10% запас. Оберіть більший план нижче, ми змінимо його з наступного періоду. Нікого не буде заблоковано.',
  'Dorosłych w bazie jest więcej niż w planie {plan} ({n} z {limit}). Mieścicie się w zapasie, plan zmienimy od kolejnego okresu.': 'У базі більше дорослих, ніж передбачає план {plan} ({n} з {limit}). Ви в межах запасу, план змінимо з наступного періоду.',
  'Dorosłych w bazie jest wyraźnie więcej niż w planie {plan} ({n} z {limit}). Wybierzcie większy plan.': 'У базі значно більше дорослих, ніж передбачає план {plan} ({n} з {limit}). Оберіть більший план.',
